var ELEMENTS=[
  {sym:'H',name:'氢',num:1},{sym:'He',name:'氦',num:2},{sym:'Li',name:'锂',num:3},
  {sym:'C',name:'碳',num:6},{sym:'N',name:'氮',num:7},{sym:'O',name:'氧',num:8},
  {sym:'Na',name:'钠',num:11},{sym:'Mg',name:'镁',num:12},{sym:'Al',name:'铝',num:13},
  {sym:'Si',name:'硅',num:14},{sym:'P',name:'磷',num:15},{sym:'S',name:'硫',num:16},
  {sym:'Cl',name:'氯',num:17},{sym:'K',name:'钾',num:19},{sym:'Ca',name:'钙',num:20},
  {sym:'Fe',name:'铁',num:26},{sym:'Cu',name:'铜',num:29},{sym:'Ag',name:'银',num:47},
  {sym:'Au',name:'金',num:79},{sym:'Hg',name:'汞',num:80}
];
function ask(rng){ rng=rng||Math.random; var e=ELEMENTS[Math.floor(rng()*ELEMENTS.length)];
  var mode=Math.floor(rng()*3);
  if(mode===0) return {type:'符号→名称', prompt:'元素 '+e.sym+' 的名称是？', answer:e.name};
  if(mode===1) return {type:'名称→符号', prompt:e.name+' 的元素符号是？', answer:e.sym};
  return {type:'序数→名称', prompt:'原子序数 '+e.num+' 的元素名称是？', answer:e.name}; }
function check(q, ans){ if(!q||ans==null) return false; ans=String(ans).trim();
  return q.type==='名称→符号' ? ans.toLowerCase()===String(q.answer).toLowerCase() : ans===String(q.answer); }
var EXPORTS={ask:ask, check:check, ELEMENTS:ELEMENTS};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PeriodicQuizForgePure = EXPORTS; }
